\label{first main result}
Suppose that $\mathcal{M}$ is a structure which is countable, binary, homogeneous, primitive, simple and 1-based.
Then $\mathcal{M}$ is strongly interpretable in a  binary random structure.

\label{definition of homogeneous}{\rm
(i) Let $V$ be a finite relational vocabulary and $\mathcal{M}$ a $V$-structure. We call $\mathcal{M}$ {\em homogeneous}
if for all finite substructures $\mathcal{A}$ and $\mathcal{B}$ of $\mathcal{M}$, every isomorphism from $\mathcal{A}$ to $\mathcal{B}$ can be extended to an
automorphism of $\mathcal{M}$.\\
(ii) We say that a structure $\mathcal{M}$, with any vocabulary, is {\em $\omega$-homogeneous} 
if whenever $n < \omega$,
$a_1, \ldots, a_n, a_{n+1}, b_1, \ldots, b_n \in M$ and $\mathrm{tp}_\mathcal{M}(a_1, \ldots, a_n) = \mathrm{tp}_\mathcal{M}(b_1, \ldots, b_n)$,
then there is $b_{n+1} \in M$ such that $\mathrm{tp}_\mathcal{M}(a_1, \ldots, a_{n+1}) = \mathrm{tp}_\mathcal{M}(b_1, \ldots, b_{n+1})$.
}

\label{properties of binary random structures}
Let $\mathcal{M}$ be a binary random structure.
Then $Th(\mathcal{M})$ is simple, has $\mathrm{SU}$-rank 1 and is 1-based with trivial dependence.

We assume that 
\begin{itemize}
\item[]{\bf $C$ is chosen so that $r$ is minimal such that~(\ref{C_i}) holds.

\label{height and existence of a coordinatizing rank one set}
The following are equivalent:
\begin{itemize}
\item[(1)] $r = 1$.
\item[(2)] There is a $\emptyset$-definable $D \subseteq M^{\mathrm{eq}}$ in which only finitely many sorts are represented
such that $M \subseteq \mathrm{acl}(D)$ and $\mathrm{SU}(d) = 1$ for every $d \in D$.
\end{itemize}

\begin{equation}\label{all element have the same acl in C_r-1}
\text{ for all } b \in M, \ \mathrm{acl}(b) \cap C_{r-1} = \mathrm{acl}(a) \cap C_{r-1}.
\end{equation}

\begin{equation}\label{C_1 is a trivial geometry}
\text{ for every } A \subseteq C_1, \ \mathrm{acl}(A) \cap C_1 = A.
\end{equation}

\label{crd is unique up to isomorphism}
If $a, b \in M$ and $\mathrm{tp}(a) = \mathrm{tp}(b)$, then $\mathrm{crd}(a)$ and $\mathrm{crd}(b)$ can be ordered as $\bar{a}$ and $\bar{b}$, respectively,
so that $\mathrm{tp}(\bar{a}) = \mathrm{tp}(\bar{b})$.

\begin{equation}\label{every member of C_1 is a coordinate of M}
\text{ for every $c \in C_1$, there is $a \in M$ such that $c \in \mathrm{crd}(a)$.}
\end{equation}

\label{M is definable in Req}
Let `$\approx$' be the $\emptyset$-definable equivalence relation on $M$ defined by $x \approx y$ if and only if $\mathrm{acl}_\mathcal{M}(x) = \mathrm{acl}_\mathcal{M}(y)$.
Then $\mathcal{M} / \negthickspace \approx$ is definable in $\mathcal{R}^{\mathrm{eq}}$  and we can use a formula $\chi(x)$ and bijection $f : \chi(\mathcal{R}^{\mathrm{eq}}) \to M / \negthickspace \approx$
as in Definition~\ref{definition of strong interpretability} with the properties that 
\begin{enumerate}
\item for all $c \in \chi(\mathcal{R}^{\mathrm{eq}})$,
$\mathrm{acl}_{\mathcal{R}^{\mathrm{eq}}}(c) \cap R = \mathrm{crd}(f(c))$ and $\mathrm{acl}_{\mathcal{R}^{\mathrm{eq}}}(c) = \mathrm{acl}_{\mathcal{R}^{\mathrm{eq}}}(\mathrm{crd}(f(c)))$, 

\item for all $c, c' \in \chi(\mathcal{R}^{\mathrm{eq}})$, $c = c'$ if and only if $\mathrm{crd}(f(c)) = \mathrm{crd}(f(c'))$, and

\item $c \in \mathrm{dcl}_{\mathcal{R}^{\mathrm{eq}}}(\mathrm{acl}_{\mathcal{R}^{\mathrm{eq}}}(c) \cap R)$ for all $c \in \chi(\mathcal{R}^{\mathrm{eq}})$.
\end{enumerate}

\begin{equation}\label{a is in definable closure of acl(a) cut with R}
\text{for every $a \in M$, $a \in \mathrm{dcl}_{\mathcal{R}^{\mathrm{eq}}}(\mathrm{crd}(a))$.}
\end{equation}

\begin{align*}
\mathrm{tp}_\mathcal{R}(\bar{b}_1, \ldots, \bar{b}_n) \ &= \ \mathrm{tp}_\mathcal{R}(\bar{b}'_1, \ldots, \bar{b}'_n) \ \Longleftrightarrow \\
\mathrm{tp}_{\mathcal{R}^{\mathrm{eq}}}(\bar{b}_1, \ldots, \bar{b}_n) \ &= \ \mathrm{tp}_{\mathcal{R}^{\mathrm{eq}}}(\bar{b}'_1, \ldots, \bar{b}'_n) \ \Longleftrightarrow \\
\mathrm{tp}_{\mathcal{R}^{\mathrm{eq}}}(f(\bar{b}_1), \ldots, f(\bar{b}_n)) \ &= \ \mathrm{tp}_{\mathcal{R}^{\mathrm{eq}}}(f(\bar{b}'_1), \ldots, f(\bar{b}'_n)) \ \Longrightarrow \\
\mathrm{tp}_\mathcal{M}(f(\bar{b}_1), \ldots, f(\bar{b}_n)) \ &= \ \mathrm{tp}_\mathcal{M}(f(\bar{b}'_1), \ldots, f(\bar{b}'_n)).
\end{align*}

\begin{equation}\label{the permuted sequence has the same type}
\mathrm{tp}_\mathcal{R}(b_1, \ldots, b_m) = \mathrm{tp}_\mathcal{R}(b_{\pi(1)}, \ldots, b_{\pi(m)}).
\end{equation}

\begin{equation}\label{pi(1) equals 2}
\text{ we assume that $\pi(1) = 2$. }
\end{equation}

\begin{equation}\label{identifications of elements}
b'_1 = b_1, \ b''_1 = b_2, \ b''_2 = b'_2,
\end{equation}

\begin{align}\label{the other sequences have the same type}
\mathrm{tp}_\mathcal{R}(b_1, b_2, \ldots, b_m) \ = \ 
\mathrm{tp}_\mathcal{R}(b'_1, b'_2, \ldots, b'_m) \ = \ 
\mathrm{tp}_\mathcal{R}(b''_1, b''_2, \ldots, b''_m). 
\end{align}

\begin{align}\label{the same type when the other sequences are permuted}
\mathrm{tp}_\mathcal{R}(b_1, b_2, \ldots, b_m) \ &= \ \mathrm{tp}_\mathcal{R}(b_{\pi(1)}, b_{\pi(2)}, \ldots, b_{\pi(m)}),  \\
\mathrm{tp}_\mathcal{R}(b'_1, b'_2, \ldots, b'_m) \ &= \ \mathrm{tp}_\mathcal{R}(b'_{\pi(1)}, b'_{\pi(2)}, \ldots, b'_{\pi(m)}) \quad \text{ and} \nonumber \\
\mathrm{tp}_\mathcal{R}(b''_1, b''_2, \ldots, b''_m) \ &= \ \mathrm{tp}_\mathcal{R}(b''_{\pi(1)}, b''_{\pi(2)}, \ldots, b''_{\pi(m)}), \nonumber
\end{align}

\begin{align}\label{equal types of some long sequences}
\mathrm{tp}_\mathcal{R}(b_1, \ldots, b_m,  c_1, \ldots, c_m)  \ &= \ \mathrm{tp}_\mathcal{R}(b_{\pi(1)}, \ldots, b_{\pi(m)},  b''_1, \ldots, b''_m)
\quad \text{ and} \\
\mathrm{tp}_\mathcal{R}(b'_1, \ldots, b'_m, c_1, \ldots, c_m) \ &= \ \mathrm{tp}_\mathcal{R}(b'_{\pi(1)}, \ldots, b'_{\pi(m)}, b''_{\pi(1)}, \ldots, b''_{\pi(m)}).
\nonumber
\end{align}

\begin{align}\label{the elements corresponding to a}
\mathrm{tp}(a, b_1, \ldots, b_m, a^*, c_1, \ldots, c_m) \ &= \ \mathrm{tp}(a_0, b_{\pi(1)}, \ldots, b_{\pi(m)}, a'', b''_1, \ldots, b''_m) \ \ \text{and} \\
\mathrm{tp}(a', b'_1, \ldots, b'_m, a^*, c_1, \ldots, c_m) \ &= \ \mathrm{tp}(a'_0, b'_{\pi(1)}, \ldots, b'_{\pi(m)}, a''_0, b''_{\pi(1)}, \ldots, b''_{\pi(m)}). \nonumber
\end{align}

\begin{align*}
&\mathrm{tp}(a, a'') = \mathrm{tp}(a, a^*) \text{ and } \mathrm{tp}(a', a'') = \mathrm{tp}(a', a^*), \text{ and hence} \\
&\mathrm{tp}_\mathcal{M}(a, a'') = \mathrm{tp}_\mathcal{M}(a, a^*) \text{ and } \mathrm{tp}_\mathcal{M}(a', a'') = \mathrm{tp}_\mathcal{M}(a', a^*).
\end{align*}

\begin{align}\label{the long sequences have the same type}
&\mathrm{tp}(b_1, \ldots, b_m, b'_1, \ldots, b'_m, b''_1, \ldots, b''_m) \\ 
= \ 
&\mathrm{tp}(b_{\sigma_1(1)}, \ldots, b_{\sigma_1(m)}, b'_{\sigma_2(1)}, \ldots, b'_{\sigma_2(m)}, c_{\sigma_3(1)}, \ldots, c_{\sigma_3(m)}). 
\nonumber
\end{align}
